fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(9, 11);
        let mut k: i32 = 0;
        while k < 4 {
            host::display::state_set(1 + k, 50);
            host::display::state_set(5 + k, 50);
            k = k + 1;
        }
    }
    host::display::clear(0x0a0a0e);
    host::display::draw_string(16, 12, "SYSTEM MONITOR", 0x808080, 1);
    host::display::draw_string(16, 44, "CPU", 0xc0c0c0, 2);
    host::display::draw_string(16, 114, "MEM", 0xc0c0c0, 2);
    host::display::draw_string(16, 184, "NET", 0xc0c0c0, 2);
    host::display::draw_string(16, 254, "DSK", 0xc0c0c0, 2);
    let bx: i32 = 70;
    let bw: i32 = w - bx - 60;
    let mut i: i32 = 0;
    while i < 4 {
        let seed: i32 = host::display::state_get(9) * 1103515245 + 12345;
        host::display::state_set(9, seed);
        let mut v: i32 = host::display::state_get(1 + i) + ((seed >> 16) & 15) - 7;
        if v < 0 { v = 0; }
        if v > 100 { v = 100; }
        host::display::state_set(1 + i, v);
        let mut pk: i32 = host::display::state_get(5 + i);
        if v > pk { pk = v; }
        if t % 10 == 0 && pk > v { pk = pk - 1; }
        host::display::state_set(5 + i, pk);
        let y: i32 = 40 + i * 70;
        host::display::fill_rect(bx, y, bw, 24, 0x1c1c24);
        host::display::fill_rect(bx, y, v * bw / 100, 24, 0x40a0e0);
        host::display::fill_rect(bx + pk * bw / 100, y - 2, 2, 28, 0xffffff);
        host::display::draw_number(bx + bw + 10, y + 4, v, 0xc0c0c0, 2);
        i = i + 1;
    }
    host::display::present();
}
